// Database row types for the Departments & Services tables and views
// (migrations 318–321), plus the L10 team tables (migration 416) and P&W songwriting (migration 417).
//
// This is not Hub UI's src/types/departments.ts. src/types/database.ts is
// generated by `supabase gen types` and must not be edited by hand. Import
// these shapes until that file includes the new tables.
//
// rocks, department_budget_links and service_owners use the column names
// the department API already selects.

export const SERVICE_CAPABILITIES = ["manage", "use", "moderate", "own"] as const;
export type ServiceCapability = (typeof SERVICE_CAPABILITIES)[number];

export const ROCK_STATUSES = ["on_track", "off_track", "done"] as const;
export type RockStatus = (typeof ROCK_STATUSES)[number];

/** A staff ministry that department pages treat as another home (317). */
export interface StaffMinistryAlias {
  id: string;
  /** The ministry being folded. The row itself is not deleted. */
  staff_ministry_id: string;
  /** The department home lookups should open. */
  resolves_to_id: string;
  reason: string;
  created_at: string;
}

/**
 * staff_ministry_resolution. One row per staff ministry.
 * is_folded is true when an alias row exists; home_* is the resolved home.
 */
export interface StaffMinistryResolution {
  id: string;
  slug: string;
  name: string;
  ministry_type: string;
  is_active: boolean;
  cluster: string | null;
  purpose: string | null;
  parent_id: string | null;
  home_id: string;
  home_slug: string;
  home_name: string;
  is_folded: boolean;
}

/** services. Catalog of keys and routes. Grants are service_owners rows. */
export interface Service {
  service_key: string;
  label: string;
  admin_href: string;
  created_at: string;
}

/**
 * service_owners. own does not imply manage. staff_ministry_id is null
 * only when any_point_leader or open_to_all is true, and only one of
 * those flags is true.
 */
export interface ServiceOwner {
  id: string;
  service_key: string;
  staff_ministry_id: string | null;
  capability: ServiceCapability;
  /** Null: any active member. 'member': members and leaders. 'leader': leaders only. */
  member_role: "member" | "leader" | null;
  any_point_leader: boolean;
  open_to_all: boolean;
  admin_href: string | null;
  created_at: string;
}

/**
 * ministry_service_access. Grants for a ministry after alias resolution.
 * The contacts any-point-leader row is not in this view.
 */
export interface MinistryServiceAccess {
  staff_ministry_id: string;
  ministry_slug: string;
  home_ministry_id: string;
  service_key: string;
  capability: ServiceCapability;
  member_role: "member" | "leader" | null;
  any_point_leader: boolean;
  open_to_all: boolean;
  admin_href: string | null;
  service_label: string;
}

/**
 * rocks. One L10 rock. quarter is 'YYYY-Q[1-4]', for example '2026-Q4'.
 * notes is extra and is not selected by the department API.
 */
export interface Rock {
  id: string;
  staff_ministry_id: string;
  quarter: string;
  title: string;
  description: string | null;
  owner_user_id: string | null;
  status: RockStatus;
  due_on: string | null;
  notes: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
  /**
   * 416: null (or not selected) for a department rock. Set for an L10 team
   * rock; staff_ministry_id is then that team's department.
   */
  team_id?: string | null;
}

/**
 * leadership_ministry_rollup. One rock or one current-cycle OKR objective.
 * source is `rock` or `okr_objective`. objective_scope is null for a rock.
 * Rocks are department rocks only (rocks.team_id IS NULL, 416); L10 team
 * rocks are not in this view.
 */
export interface LeadershipMinistryRollup {
  staff_ministry_id: string;
  ministry_slug: string;
  ministry_name: string;
  ministry_type: string;
  ministry_is_active: boolean;
  source: "rock" | "okr_objective";
  source_id: string;
  title: string;
  /** Rock status, or `current` for an OKR objective on the current cycle. */
  status: string;
  objective_scope: string | null;
  owner_user_id: string | null;
  due_on: string | null;
  /** Rock quarter ('2026-Q4'). Null for an OKR objective. */
  quarter: string | null;
  description: string | null;
  notes: string | null;
  updated_at: string;
}

/**
 * department_budget_links. Several ZAR links per ministry are allowed.
 * year defaults to the calendar year of the insert and is not read by the API.
 */
export interface DepartmentBudgetLink {
  id: string;
  staff_ministry_id: string;
  finance_project_id: string | null;
  budget_cents: number;
  spend_cents: number;
  currency: "ZAR";
  notes: string | null;
  year: number;
  updated_at: string;
  updated_by: string | null;
  created_at: string;
}

// ── L10 teams (migration 416) ────────────────────────────────────────
// A department can run several L10 teams; P&W seeds production, live and
// team-3. Every row below carries team_id. Read/write = team members,
// leaders of the team's department, and admins. l10_teams writes are
// department leaders and admins only; l10_team_members writes add the
// team's own leaders.

/** Postgres error message (SQLSTATE 42501) when a caller may not set an attendee rating. */
export const L10_RATING_NOT_ALLOWED = "l10_rating_not_allowed" as const;

/**
 * Postgres error message (SQLSTATE 42501) when a signed-in user (admins and
 * overseers included) changes meeting_id, profile_id or team_id on an
 * attendee row. Only service_role may; to fix a row, delete and re-insert.
 */
export const L10_ATTENDEE_IMMUTABLE = "l10_attendee_immutable" as const;

/** Postgres error message (SQLSTATE 42501) when a signed-in user writes a locked auto headline. */
export const L10_AUTO_HEADLINE_LOCKED = "l10_auto_headline_locked" as const;

/** Postgres error message (SQLSTATE 23514) when service_role writes an auto headline without both meeting ids. */
export const L10_AUTO_HEADLINE_INCOMPLETE = "l10_auto_headline_incomplete" as const;

/** Unique index hit (SQLSTATE 23505) when a team already has an open meeting. */
export const L10_ONE_OPEN_MEETING_INDEX = "l10_meetings_one_open_per_team" as const;

/** Unique index hit (SQLSTATE 23505) for a second auto recap of the same meeting in the same meeting. */
export const L10_ONE_AUTO_RECAP_INDEX = "l10_headlines_one_auto_recap" as const;

export const L10_TEAM_ROLES = ["member", "leader"] as const;
export type L10TeamRole = (typeof L10_TEAM_ROLES)[number];

export const L10_ISSUE_STATUSES = ["identified", "discussed", "solved"] as const;
export type L10IssueStatus = (typeof L10_ISSUE_STATUSES)[number];

export const L10_MEASURABLE_UNITS = ["number", "percent", "currency", "yes_no"] as const;
export type L10MeasurableUnit = (typeof L10_MEASURABLE_UNITS)[number];

export const L10_GOAL_DIRECTIONS = ["at_least", "at_most", "exactly"] as const;
export type L10GoalDirection = (typeof L10_GOAL_DIRECTIONS)[number];

/** The seven L10 agenda segments, in meeting order. Keys of segment_timings. */
export const L10_SEGMENTS = [
  "segue",
  "scorecard",
  "rock_review",
  "headlines",
  "todo_list",
  "ids",
  "conclude",
] as const;
export type L10Segment = (typeof L10_SEGMENTS)[number];

/**
 * One segment's timing. Each value is null / absent, or a strict ISO-8601
 * timestamp WITH an offset, e.g. `new Date().toISOString()`
 * ("2026-11-26T07:00:00.000Z") or "2026-11-26T09:00+02:00". No offset,
 * date-only, a space separator or an impossible date fails the
 * l10_meetings_segment_timings_shape CHECK (23514), as does
 * ended_at < started_at when both are set.
 */
export interface L10SegmentTiming {
  started_at?: string | null;
  ended_at?: string | null;
}
export type L10SegmentTimings = Partial<Record<L10Segment, L10SegmentTiming>>;

/** l10_teams. Unique on (department_id, slug). */
export interface L10Team {
  id: string;
  /** staff_ministries.id of the owning department. */
  department_id: string;
  /** Lowercase kebab case: 'production', 'live', 'team-3'. */
  slug: string;
  name: string;
  /** ISO weekday, 1 = Monday … 7 = Sunday. */
  meeting_weekday: number | null;
  /** 'HH:MM:SS' local time in meeting_timezone. */
  meeting_time: string | null;
  meeting_timezone: string;
  facilitator_id: string | null;
  /** Slack channel id for the post-meeting recap. Null = no channel recap. */
  slack_channel_id: string | null;
  /**
   * Paired team (same department, never itself) whose latest ended meeting
   * is recapped as an auto headline when this team's meeting starts.
   * Seeded production ↔ live; team-3 null. Cleared if that team is deleted.
   */
  recap_source_team_id: string | null;
  sort_order: number;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

/** l10_team_members. Unique on (team_id, profile_id). profile_id is users.id. */
export interface L10TeamMember {
  id: string;
  team_id: string;
  profile_id: string;
  role: L10TeamRole;
  created_at: string;
  updated_at: string;
}

/**
 * l10_meetings. ended_at is null while the meeting runs. A team has at most
 * one open meeting (unique index l10_meetings_one_open_per_team): starting
 * a second one before ending the first fails with 23505.
 */
export interface L10Meeting {
  id: string;
  team_id: string;
  /** The team's department (staff_ministries.id). Filled from team_id by a trigger (420); don't send it. */
  department_id: string;
  started_at: string;
  ended_at: string | null;
  facilitator_id: string | null;
  segment_timings: L10SegmentTimings;
  notes: string | null;
  /** Idempotency claim for the recap posted to L10Team.slack_channel_id. */
  recap_posted_at: string | null;
  /** Team-level follow-up sent. Per-person DMs: L10MeetingAttendee.followup_sent_at. */
  followup_sent_at: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/** l10_meeting_attendees. Unique on (meeting_id, profile_id). */
export interface L10MeetingAttendee {
  id: string;
  team_id: string;
  meeting_id: string;
  profile_id: string;
  /**
   * 1–10, null until rated. A DB trigger lets only the attendee, a team
   * leader, an overseer (admin / department leader) or this meeting's
   * facilitator set or change it; anyone else gets 42501
   * `l10_rating_not_allowed`. service_role is exempt.
   */
  rating: number | null;
  /** When this attendee's Slack follow-up DM went out. */
  followup_sent_at: string | null;
  created_at: string;
  updated_at: string;
}

/** l10_measurables. One scorecard row. */
export interface L10Measurable {
  id: string;
  team_id: string;
  title: string;
  owner_id: string | null;
  unit: L10MeasurableUnit;
  /** numeric comes back from PostgREST as a number (or a string for huge values). */
  goal_value: number | null;
  goal_direction: L10GoalDirection;
  sort_order: number;
  is_active: boolean;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/** l10_measurable_values. Unique on (measurable_id, week_start). */
export interface L10MeasurableValue {
  id: string;
  team_id: string;
  measurable_id: string;
  /** 'YYYY-MM-DD', always a Monday (SAST calendar date). */
  week_start: string;
  /** Null = not entered. yes_no stores 1 or 0. */
  value: number | null;
  note: string | null;
  entered_by: string | null;
  created_at: string;
  updated_at: string;
}

/** l10_todos. done_at is set exactly when done is true. */
export interface L10Todo {
  id: string;
  team_id: string;
  title: string;
  owner_id: string | null;
  due_on: string | null;
  done: boolean;
  done_at: string | null;
  /** Meeting it came out of. Set to null if that meeting is deleted. */
  source_meeting_id: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * l10_issues. Team IDS list. An issue belongs to the team and stays open
 * (identified/discussed) at every meeting until solved; nothing is copied.
 * solved_at is set exactly when status is 'solved'.
 */
export interface L10Issue {
  id: string;
  team_id: string;
  title: string;
  description: string | null;
  owner_id: string | null;
  status: L10IssueStatus;
  /** 1–3 top-three rank, null = unranked. */
  priority: number | null;
  solved_at: string | null;
  /** Meeting where it was raised. */
  source_meeting_id: string | null;
  /** Meeting where it was solved. Only non-null when status is 'solved'. */
  resolved_meeting_id: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * l10_headlines. A normal headline has an author. An auto headline
 * (is_auto) is the Hub's cross-team recap: only service_role creates,
 * edits or deletes it, and signed-in team members may change only
 * dismissed_at (anything else: 42501 `l10_auto_headline_locked`).
 */
export interface L10Headline {
  id: string;
  team_id: string;
  /** The team's department (staff_ministries.id). Filled from team_id by a trigger (420); don't send it. */
  department_id: string;
  body: string;
  /** Required unless is_auto. Deleting the user deletes their headlines. */
  author_id: string | null;
  /** Meeting the headline appears in. Always set on auto rows when written. */
  source_meeting_id: string | null;
  is_auto: boolean;
  /**
   * The paired team's ended meeting this auto row recaps. Only on auto rows;
   * must be in the same department (composite FK, 420: 23503 otherwise);
   * unique per (source_meeting_id, recap_of_meeting_id). Becomes null if
   * that meeting is deleted.
   */
  recap_of_meeting_id: string | null;
  /** Null = showing. Any team member may set or clear it. */
  dismissed_at: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * A team rock is a public.rocks row with team_id set (416). staff_ministry_id
 * is then the team's department. Department rocks keep team_id null.
 */
export interface L10TeamRock extends Rock {
  team_id: string;
}

// ── P&W songwriting (migration 417) ──────────────────────────────────
// Separate block from the L10 types (416) on purpose: both PRs append to
// this file, so a merge keeps both blocks. Read/write: active
// prayer_and_worship members and admins only.

export const PW_CONTINENTS = [
  "africa",
  "asia",
  "europe",
  "north_america",
  "south_america",
  "oceania",
  "antarctica",
] as const;
export type PwContinent = (typeof PW_CONTINENTS)[number];

export const PW_NATION_STATUSES = ["active", "tentative"] as const;
export type PwNationStatus = (typeof PW_NATION_STATUSES)[number];

export const PW_TRAINING_STATUSES = ["completed", "draft"] as const;
export type PwTrainingStatus = (typeof PW_TRAINING_STATUSES)[number];

export const PW_TRAINING_SOURCES = ["imported", "hub"] as const;
export type PwTrainingSource = (typeof PW_TRAINING_SOURCES)[number];

/** draft = being written; written = finished; recorded = has a recording; released = shared publicly. */
export const PW_SONG_STATUSES = ["draft", "written", "recorded", "released"] as const;
export type PwSongStatus = (typeof PW_SONG_STATUSES)[number];

/** pw_songwriting_leads.kind (424). */
export const PW_LEAD_KINDS = ["person", "organisation", "group"] as const;
export type PwLeadKind = (typeof PW_LEAD_KINDS)[number];

/** pw_songwriting_leads.status (424). Default 'new'. */
export const PW_LEAD_STATUSES = ["new", "to_contact", "waiting", "connected", "closed"] as const;
export type PwLeadStatus = (typeof PW_LEAD_STATUSES)[number];

/**
 * Postgres error message (SQLSTATE 42501) when a signed-in caller changes
 * pw_songwriting_leads.created_by, or edits a lead event (append-only).
 */
export const PW_SONGWRITING_ACTOR_LOCKED = "pw_songwriting_actor_locked" as const;

/** Postgres error message (SQLSTATE 42501) when a signed-in caller sets pw_songwriting_leads.last_contact_at. */
export const PW_LEAD_LAST_CONTACT_DERIVED = "pw_lead_last_contact_derived" as const;

/** Postgres error message (SQLSTATE 23514) when service_role writes a lead event without by. */
export const PW_LEAD_EVENT_ACTOR_REQUIRED = "pw_lead_event_actor_required" as const;

/** pw_nations. slug is unique; iso_code is unique where set (424). */
export interface PwNation {
  id: string;
  name: string;
  slug: string;
  continent: PwContinent | null;
  status: PwNationStatus;
  notes: string | null;
  /** ISO 3166-1 alpha-2, two capital letters ("ZA"). Null = not set yet (424). */
  iso_code: string | null;
  /** The nation's languages as display strings; [] when none recorded (424). */
  languages: string[];
  created_at: string;
  updated_at: string;
}

/** pw_songwriting_trainings. Null counts are unknown, not zero. */
export interface PwSongwritingTraining {
  id: string;
  year: number;
  /** 1–12. */
  month: number;
  /**
   * Optional day (424): a date column, so send 'YYYY-MM-DD', never a
   * timestamp (a timestamp is cast in the session time zone and can land
   * in the next or previous month). Must fall in year/month, which stay
   * required; null = month only (every imported row).
   */
  training_date: string | null;
  location_text: string | null;
  nation_id: string | null;
  audience_label: string | null;
  people_trained: number | null;
  songs_workshop: number | null;
  songs_post: number | null;
  notes: string | null;
  languages: string[];
  status: PwTrainingStatus;
  source: PwTrainingSource;
  /** Set exactly when source is 'imported'. Hub-created rows leave it null. */
  import_key: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/** pw_training_facilitators. Unique on (training_id, display_name). */
export interface PwTrainingFacilitator {
  id: string;
  training_id: string;
  /** Hub user when known; display_name is always set. */
  person_id: string | null;
  display_name: string;
  created_at: string;
  updated_at: string;
}

/** pw_songs. */
export interface PwSong {
  id: string;
  title: string;
  language: string | null;
  nation_id: string | null;
  source_training_id: string | null;
  status: PwSongStatus;
  notes: string | null;
  /** 'YYYY-MM-DD'. */
  written_on: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * pw_songwriting_leads (424): people, organisations or groups to follow up,
 * by nation and/or source training. No contact details (the CRM has them).
 * The API adds owner_name (from owner_user_id) for #745's SongwritingLead.
 */
export interface PwSongwritingLead {
  id: string;
  /** What the card shows. Always set, even when contact_user_id is. */
  label: string;
  kind: PwLeadKind;
  /** Hub user, when the lead has an account. */
  contact_user_id: string | null;
  source_training_id: string | null;
  nation_id: string | null;
  note: string | null;
  /** Who follows up. Null = unassigned. */
  owner_user_id: string | null;
  status: PwLeadStatus;
  /**
   * Derived: the latest lead event's `at` (null when there are none). Kept
   * by the database; signed-in callers cannot set it (42501
   * pw_lead_last_contact_derived). Log a contact instead.
   */
  last_contact_at: string | null;
  /** Set to the signed-in caller on insert (whatever is sent); cannot change (42501 pw_songwriting_actor_locked). */
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * pw_songwriting_lead_events (424): one "Log contact". Append-only for
 * signed-in callers (no update; 42501). Delete = the author or an admin, and
 * last_contact_at is recomputed. Deleting the lead deletes these.
 */
export interface PwSongwritingLeadEvent {
  id: string;
  lead_id: string;
  /** When the contact happened. Defaults to now(). */
  at: string;
  /**
   * Hub user who logged it: the signed-in caller (whatever is sent).
   * service_role must name one (23514 pw_lead_event_actor_required).
   * Null only after that user is deleted.
   */
  by: string | null;
  note: string | null;
  created_at: string;
  updated_at: string;
}

/** pw_song_writers. Unique on (song_id, display_name). */
export interface PwSongWriter {
  id: string;
  song_id: string;
  person_id: string | null;
  display_name: string;
  created_at: string;
  updated_at: string;
}

/**
 * pw_songwriting_totals (view, security_invoker). Completed trainings only.
 * scope 'overall': year and nation null. 'year': year set. 'nation':
 * nation_id and nation_name set. Unknown counts sum as 0.
 */
export interface PwSongwritingTotals {
  scope: "overall" | "year" | "nation";
  year: number | null;
  nation_id: string | null;
  nation_name: string | null;
  trainings: number;
  people_trained: number;
  songs_workshop: number;
  songs_post: number;
  /** songs_workshop + songs_post. */
  songs_total: number;
  /** pw_songs rows whose source training is in this group. */
  songs_logged: number;
  nations: number;
  tentative_nations: number;
  continents: number;
}
